#!/bin/sh
# Builds kaggle/speaker/kernel.py: ECAPA speaker embeddings (src/speaker.py) on a CPU-only kernel (no GPU quota).
cd "$(dirname "$0")/.."
B64=$(base64 < src/speaker.py | tr -d '\n')
cat > kaggle/speaker/kernel.py <<PY
# Kaggle kernel: speaker embeddings. Generated by kaggle/build_speaker.sh from src/speaker.py.
import base64, glob, os, subprocess, sys
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "speechbrain"], check=True)
os.makedirs("/tmp/src", exist_ok=True)
open("/tmp/src/speaker.py", "w").write(base64.b64decode("$B64").decode())
open("/tmp/src/cv.py", "w").write("from pathlib import Path\nDATA = ROOT = Path('/kaggle/working')\n")
csv = glob.glob("/kaggle/input/**/train.csv", recursive=True)
assert csv, "competition data not attached"
subprocess.run([sys.executable, "/tmp/src/speaker.py", "--data", os.path.dirname(csv[0]), "--out", "/kaggle/working"], check=True)
import shutil; shutil.rmtree("/kaggle/working/ecapa_model", ignore_errors=True)
print(sorted(os.listdir("/kaggle/working")))
PY
echo "built kaggle/speaker/kernel.py"
